import math

def is_perfect_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n, sqrt_n

solutions = []

for b in range(1, 16):
    # C = 2^(b+1) - 1
    C = (1 << (b + 1)) - 1

    # D^2 = C^2 - 8 * 3^b
    D_squared = C**2 - 8 * (3**b)

    is_square, D = is_perfect_square(D_squared)

    if is_square:
        # Solutions for a are (C +/- D) / 2

        # Check for integer solutions and positivity
        # Since C and D are integers, we check if C +/- D is even.

        # Solution 1: a1 = (C + D) / 2
        if (C + D) % 2 == 0:
            a1 = (C + D) // 2
            if a1 > 0:
                solutions.append((a1, b))

        # Solution 2: a2 = (C - D) / 2
        if (C - D) % 2 == 0:
            a2 = (C - D) // 2
            if a2 > 0:
                solutions.append((a2, b))

print("Found solutions (a, b):")
for sol in solutions:
    print(sol)

# Also print the summary to facilitate note writing
print("\nSummary:")
if solutions:
    print(f"Total solutions found: {len(solutions)}")
else:
    print("No solutions found in the range b=1 to b=15.")

